// 擴充模型：地景（牧場、漁港、海灘、水壩、動物園、風車公園）
// 由主檔 models.js 的 buildModel 分派：回傳 true 表示已處理，false 表示不是這裡的模型。
// h 內的工具（單位空間：底面約 [-0.5, 0.5]，y 向上，1 單位 ≈ 模型縮放前的一格）：
//   h.box(pos, size, color, rot?)   方塊            h.b(pos, size, color, rot?)   圓角方塊（小於 0.06 會退回方塊）
//   h.cy(pos, r, height, color, rot?) 圓柱           h.cone(pos, r, height, color) 圓錐
//   h.sphere(pos, r, color)         球              h.dome(pos, r, height, color) 半球
//   h.ring(pos, r, color, rot?)     環              h.hip(pos, size, color)       四角屋頂（底面 1×1，位置是屋頂中心）
//   h.glow(pos, size, color?, rot?) 發光方塊（夜晚亮）  h.glass(pos, size, color?)   玻璃
//   h.post(x, z, height, color?, r?) 立柱            h.windows(y, z, n, span?, w?, hgt?) 一排窗
//   h.bench(x, z, ry?) 長椅         h.plant(x, z, k?) 樹   h.tree(x, z, k, kind?) 樹（kind "cone"/"round"）
//   h.p(kind, pos, size, color, rot?) 任意零件（kind 見 kit.js）
//   h.C 調色盤（cream, ink, coral, yellow, stone, wood, green, teal, white, window, glass, leaf, dark, sand）、h.accent 該區主色
// rot 為 Euler [x, y, z]，任何軸都可以（主檔會正確合成整體朝向）。
const WATER = 0x4f8fb8, GRASS = 0x8fb36b, CONCRETE = 0xbdb7ad;

export function landscapeModels(kind, h) {
  const { box, b, cy, cone, sphere, dome, ring, hip, glow, p, tree, C, accent } = h;
  switch (kind) {
    // ── 酪農／休閒牧場：紅穀倉、銀色筒倉、白圍籬、乳牛、乾草捲 ──
    case "farm": {
      box([0, 0.02, 0], [1.3, 0.04, 1.1], GRASS); // 草地
      b([-0.3, 0.21, -0.15], [0.5, 0.34, 0.4], 0xb8412f); // 紅穀倉
      hip([-0.3, 0.46, -0.15], [0.56, 0.16, 0.46], 0x8e2f22); // 下層屋頂
      hip([-0.3, 0.58, -0.15], [0.42, 0.14, 0.34], 0x8e2f22); // 上層屋頂（疊成 gambrel）
      box([-0.3, 0.14, 0.056], [0.14, 0.2, 0.01], C.white); // 穀倉大門
      glow([-0.3, 0.33, 0.056], [0.1, 0.08, 0.01]); // 閣樓窗
      cy([0.1, 0.32, -0.38], 0.1, 0.6, 0xc8ccd0); // 筒倉
      for (const y of [0.22, 0.42]) cy([0.1, y, -0.38], 0.105, 0.015, 0xa8adb3); // 筒倉箍帶
      dome([0.1, 0.62, -0.38], 0.1, 0.1, 0xa8adb3); // 筒倉圓頂
      // 白色圍籬（牧場圍場 x∈[0.1,0.6], z∈[-0.1,0.5]）
      for (const [x, z] of [[0.1, -0.1], [0.6, -0.1], [0.1, 0.5], [0.6, 0.5], [0.35, -0.1], [0.35, 0.5]]) cy([x, 0.1, z], 0.012, 0.12, C.white);
      for (const z of [-0.1, 0.5]) box([0.35, 0.13, z], [0.52, 0.015, 0.015], C.white);
      for (const x of [0.1, 0.6]) box([x, 0.13, 0.2], [0.015, 0.015, 0.62], C.white);
      // 乳牛：白身黑斑
      const cow = (x, z, ry) => {
        const r = [0, ry, 0];
        box([x, 0.13, z], [0.16, 0.09, 0.09], C.white, r); // 身體
        box([x + 0.1, 0.16, z], [0.06, 0.06, 0.06], C.white, r); // 頭（粗略，朝向跟著 ry）
        for (const d of [-0.05, 0.05]) box([x + d, 0.065, z], [0.02, 0.05, 0.08], C.white, r); // 前後腿
        box([x - 0.03, 0.165, z], [0.06, 0.03, 0.1], C.ink, r); // 背上黑斑
        box([x + 0.03, 0.115, z], [0.04, 0.05, 0.1], C.ink, r); // 側腹黑斑
      };
      cow(0.25, 0.05, 0.3); cow(0.45, 0.3, -1.2); cow(0.22, 0.38, 2.0);
      for (const x of [-0.35, -0.22]) cy([x, 0.105, 0.35], 0.06, 0.1, 0xd8b85a, [0, 0, Math.PI / 2]); // 乾草捲（橫放）
      tree(-0.58, 0.35, 0.4);
      return true;
    }
    // ── 漁港：混凝土碼頭、漁船、燈塔、魚市棚 ──
    case "harbor": {
      p("cylinder", [0, 0.0125, 0], [1.5, 0.025, 1.3], WATER); // 海面
      box([0, 0.06, -0.25], [1.3, 0.08, 0.3], 0xb9b2a8); // 碼頭
      for (const x of [-0.4, -0.15, 0.1, 0.4]) cy([x, 0.13, -0.14], 0.02, 0.06, C.ink); // 繫船柱
      const boat = (x, z, stripe) => {
        box([x, 0.07, z], [0.3, 0.08, 0.13], C.white); // 船身
        p("cone", [x + 0.2, 0.07, z], [0.13, 0.12, 0.13], C.white, [0, 0, -Math.PI / 2]); // 尖船首
        box([x, 0.095, z], [0.31, 0.02, 0.14], stripe); // 船舷彩帶
        box([x - 0.05, 0.145, z], [0.1, 0.07, 0.09], C.cream); // 駕駛艙
        glow([x - 0.05, 0.15, z + 0.046], [0.07, 0.03, 0.01]); // 艙窗
        cy([x + 0.06, 0.22, z], 0.008, 0.26, C.ink); // 桅杆
      };
      boat(-0.4, 0.12, C.coral); boat(0.0, 0.2, accent); boat(0.4, 0.1, C.teal);
      cy([-0.55, 0.3, -0.25], 0.07, 0.4, C.white); // 燈塔
      cy([-0.55, 0.3, -0.25], 0.072, 0.05, 0xd23b2a); // 紅帶
      cy([-0.55, 0.53, -0.25], 0.075, 0.06, 0xd23b2a); // 紅色塔頂
      glow([-0.55, 0.6, -0.25], [0.08, 0.08, 0.08], C.yellow); // 燈室
      cone([-0.55, 0.68, -0.25], 0.08, 0.08, 0xd23b2a);
      for (const [x, z] of [[0.05, -0.38], [0.45, -0.38], [0.05, -0.12], [0.45, -0.12]]) cy([x, 0.25, z], 0.015, 0.3, C.wood); // 魚市棚柱
      hip([0.25, 0.44, -0.25], [0.5, 0.1, 0.34], accent); // 棚頂
      box([0.25, 0.14, -0.25], [0.3, 0.08, 0.14], C.wood); // 攤台
      box([0.2, 0.2, -0.25], [0.08, 0.04, 0.08], 0x5fb0d8); // 魚箱
      box([0.3, 0.2, -0.25], [0.08, 0.04, 0.08], C.yellow);
      return true;
    }
    // ── 海灘：沙灘、浪花線、陽傘、救生塔、木麻黃、衝浪板 ──
    case "beach": {
      p("cylinder", [-0.4, 0.0125, 0], [0.7, 0.025, 1.2], WATER); // 海水
      box([0.2, 0.02, 0], [1.1, 0.04, 1.1], C.sand); // 沙灘
      box([-0.3, 0.045, 0], [0.14, 0.012, 1.15], 0x8fd0e0); // 岸邊淺水
      box([-0.3, 0.054, 0], [0.025, 0.006, 1.1], C.white); // 浪花線
      box([-0.45, 0.03, 0], [0.02, 0.006, 1.05], C.white);
      [[0.05, -0.3, C.coral], [0.3, -0.1, C.yellow], [0.1, 0.25, C.teal], [0.4, 0.35, accent]].forEach(([x, z, c]) => {
        cy([x, 0.14, z], 0.008, 0.2, C.ink); // 傘柱
        cone([x, 0.27, z], 0.12, 0.08, c); // 傘面
        box([x + 0.08, 0.045, z], [0.1, 0.01, 0.16], c); // 浴巾
      });
      for (const [dx, dz] of [[-0.07, -0.06], [0.07, -0.06], [-0.07, 0.06], [0.07, 0.06]]) cy([0.5 + dx, 0.15, -0.3 + dz], 0.012, 0.22, C.wood); // 救生塔柱
      box([0.5, 0.3, -0.3], [0.2, 0.12, 0.18], C.coral); // 救生塔小屋
      hip([0.5, 0.4, -0.3], [0.26, 0.08, 0.24], C.white);
      cy([0.6, 0.5, -0.38], 0.006, 0.16, C.ink); // 旗桿
      box([0.63, 0.55, -0.38], [0.06, 0.04, 0.005], C.yellow);
      for (const [x, z] of [[0.66, -0.05], [0.68, 0.2], [0.6, 0.5]]) {
        cy([x, 0.14, z], 0.012, 0.2, C.wood);
        p("cone", [x, 0.32, z], [0.14, 0.36, 0.14], 0x5a7a52, [0, 0, 0.18]); // 木麻黃（被風吹斜）
      }
      box([0.2, 0.14, 0.05], [0.07, 0.26, 0.015], C.white, [0.15, 0, 0]); // 插在沙裡的衝浪板
      box([0.2, 0.14, 0.05], [0.025, 0.27, 0.025], accent, [0.15, 0, 0]);
      return true;
    }
    // ── 水庫：弧形壩牆（三段）、溢洪道、壩後水面、取水塔、觀景台 ──
    case "dam": {
      box([0, 0.02, 0.3], [1.4, 0.04, 0.8], 0x8a9a7a); // 下游地面
      box([0, 0.14, -0.4], [1.3, 0.28, 0.7], 0x7d8c68); // 壩後台地
      p("cylinder", [0, 0.29, -0.42], [1.2, 0.03, 0.62], WATER); // 水庫水面
      box([0, 0.2, -0.05], [0.5, 0.4, 0.1], CONCRETE); // 壩牆中段
      box([-0.43, 0.2, 0.03], [0.42, 0.4, 0.1], CONCRETE, [0, 0.35, 0]); // 左段（向下游彎）
      box([0.43, 0.2, 0.03], [0.42, 0.4, 0.1], CONCRETE, [0, -0.35, 0]); // 右段
      box([0, 0.41, -0.05], [0.52, 0.02, 0.12], 0xa8a29a); // 壩頂道路
      box([-0.43, 0.41, 0.03], [0.44, 0.02, 0.12], 0xa8a29a, [0, 0.35, 0]);
      box([0.43, 0.41, 0.03], [0.44, 0.02, 0.12], 0xa8a29a, [0, -0.35, 0]);
      box([0, 0.22, 0.175], [0.26, 0.02, 0.5], 0xd3cfc7, [0.8, 0, 0]); // 溢洪道斜坡
      glow([0, 0.231, 0.1865], [0.14, 0.012, 0.48], 0x8fe0ff, [0.8, 0, 0]); // 溢流水痕
      p("cylinder", [0, 0.045, 0.45], [0.4, 0.02, 0.2], WATER); // 消能池
      cy([-0.25, 0.4, -0.3], 0.05, 0.28, 0xc9c3b9); // 取水塔
      cy([-0.25, 0.555, -0.3], 0.06, 0.03, 0x8c8780);
      glow([-0.25, 0.48, -0.245], [0.04, 0.04, 0.01]);
      box([-0.25, 0.42, -0.17], [0.04, 0.015, 0.22], C.ink); // 塔橋
      box([0.38, 0.07, 0.32], [0.3, 0.06, 0.24], 0xb5afa5); // 觀景台
      for (const x of [0.25, 0.38, 0.51]) cy([x, 0.14, 0.43], 0.008, 0.08, C.ink);
      box([0.38, 0.18, 0.43], [0.3, 0.01, 0.01], C.ink); // 欄杆
      dome([-0.6, 0, 0.1], 0.18, 0.4, 0x6f8a5a); // 兩側山坡
      dome([0.6, 0, 0.1], 0.18, 0.4, 0x6f8a5a);
      tree(-0.55, 0.4, 0.3, "cone"); tree(0.55, 0.42, 0.3, "cone"); tree(-0.4, 0.6, 0.3, "cone");
      return true;
    }
    // ── 野生動物園：圍場、長頸鹿、大象、斑馬、紅鶴、售票亭 ──
    case "zoo": {
      box([0, 0.02, 0], [1.3, 0.04, 1.1], 0x9db574); // 草地
      for (const z of [-0.45, 0.3]) box([-0.175, 0.07, z], [0.88, 0.06, 0.03], C.stone); // 圍場矮牆
      for (const x of [-0.6, 0.25]) box([x, 0.07, -0.075], [0.03, 0.06, 0.78], C.stone);
      for (const [x, z] of [[-0.6, -0.45], [0.25, -0.45], [-0.6, 0.3], [0.25, 0.3]]) cy([x, 0.12, z], 0.012, 0.16, C.wood); // 角柱
      const giraffe = 0xe8a548, gbrown = 0x9c5a2a;
      box([-0.4, 0.17, -0.2], [0.16, 0.08, 0.08], giraffe); // 長頸鹿身體
      for (const d of [-0.05, 0.05]) box([-0.4 + d, 0.1, -0.2], [0.03, 0.12, 0.07], giraffe);
      box([-0.33, 0.3, -0.2], [0.04, 0.22, 0.04], giraffe, [0, 0, -0.35]); // 長脖子
      box([-0.28, 0.42, -0.2], [0.07, 0.04, 0.04], giraffe); // 頭
      box([-0.42, 0.18, -0.2], [0.05, 0.03, 0.09], gbrown); // 斑紋
      box([-0.33, 0.3, -0.2], [0.045, 0.04, 0.045], gbrown, [0, 0, -0.35]);
      const grey = 0x8f8f96;
      b([0, 0.14, -0.2], [0.2, 0.14, 0.14], grey); // 大象身體
      for (const d of [-0.06, 0.06]) box([d, 0.05, -0.2], [0.05, 0.08, 0.12], grey);
      sphere([0.13, 0.17, -0.2], 0.06, grey); // 頭
      box([0.11, 0.18, -0.2], [0.03, 0.07, 0.17], 0x7f7f86); // 耳朵
      cy([0.19, 0.1, -0.2], 0.015, 0.12, grey, [0, 0, -0.3]); // 象鼻
      box([-0.4, 0.11, 0.12], [0.16, 0.08, 0.08], C.white); // 斑馬身體
      for (const d of [-0.05, 0.05]) box([-0.4 + d, 0.05, 0.12], [0.03, 0.08, 0.07], C.white);
      box([-0.3, 0.16, 0.12], [0.07, 0.05, 0.05], C.white); // 頭
      for (let i = 0; i < 3; i++) box([-0.44 + i * 0.04, 0.11, 0.12], [0.012, 0.09, 0.09], C.ink); // 黑條紋
      const pink = 0xf49ab0;
      cy([0.1, 0.07, 0.12], 0.005, 0.1, pink); // 紅鶴單腳
      sphere([0.1, 0.15, 0.12], 0.04, pink);
      cy([0.13, 0.2, 0.12], 0.008, 0.1, pink, [0, 0, -0.3]); // 脖子
      sphere([0.15, 0.255, 0.12], 0.018, pink);
      cy([0.16, 0.07, 0.22], 0.005, 0.1, pink); // 第二隻紅鶴
      sphere([0.16, 0.15, 0.22], 0.04, pink);
      cy([0.19, 0.2, 0.22], 0.008, 0.1, pink, [0, 0, -0.3]);
      box([0.5, 0.15, 0], [0.24, 0.26, 0.24], C.cream); // 售票亭
      hip([0.5, 0.33, 0], [0.3, 0.1, 0.3], accent);
      glow([0.5, 0.42, 0], [0.26, 0.07, 0.03], C.yellow); // 招牌
      glow([0.5, 0.17, 0.125], [0.12, 0.08, 0.01]); // 售票窗
      tree(0.55, -0.4, 0.35); tree(0.55, 0.4, 0.3);
      return true;
    }
    // ── 荷蘭村：池塘、荷蘭風車、木拱橋、鬱金香花圃 ──
    case "windmillpark": {
      box([0, 0.02, 0], [1.3, 0.04, 1.1], GRASS); // 草地
      p("cylinder", [0.15, 0.045, 0.15], [0.8, 0.02, 0.6], 0x5f9bbf); // 池塘
      const mx = -0.35, mz = -0.15;
      cy([mx, 0.12, mz], 0.15, 0.2, 0x6b4a36); // 風車下層
      cy([mx, 0.33, mz], 0.12, 0.24, 0x4e3a2e); // 風車上層（收窄）
      ring([mx, 0.23, mz], 0.16, C.wood, [Math.PI / 2, 0, 0]); // 環形平台
      cone([mx, 0.52, mz], 0.14, 0.14, 0x3f3a3a); // 帽頂
      glow([mx, 0.1, mz + 0.155], [0.06, 0.1, 0.01], C.window); // 門
      glow([mx, 0.35, mz + 0.125], [0.05, 0.06, 0.01]); // 窗
      const hy = 0.47, hz = mz + 0.15, tilt = -0.15;
      sphere([mx, hy, hz], 0.03, C.ink); // 葉片軸心
      for (let i = 0; i < 4; i++) {
        const a = Math.PI / 4 + (i * Math.PI) / 2, ly = 0.14 * Math.sin(a);
        box([mx + 0.14 * Math.cos(a), hy + ly * Math.cos(tilt), hz + ly * Math.sin(tilt)], [0.24, 0.05, 0.012], C.wood, [tilt, 0, a]); // 四片葉片（略向後仰）
      }
      box([0.15, 0.1, 0.15], [0.12, 0.02, 0.22], C.wood); // 拱橋中段
      box([0.15, 0.085, 0.4], [0.12, 0.02, 0.3], C.wood, [0.18, 0, 0]); // 兩側斜坡
      box([0.15, 0.085, -0.1], [0.12, 0.02, 0.3], C.wood, [-0.18, 0, 0]);
      for (const [dx, dz] of [[-0.055, -0.08], [0.055, -0.08], [-0.055, 0.08], [0.055, 0.08]]) cy([0.15 + dx, 0.15, 0.15 + dz], 0.008, 0.08, C.white); // 橋欄柱
      for (const dx of [-0.055, 0.055]) box([0.15 + dx, 0.19, 0.15], [0.01, 0.01, 0.2], C.white);
      const tulips = [C.coral, C.yellow, 0xf08aa0];
      for (const [z, off] of [[-0.36, 0], [-0.48, 1]]) {
        box([0.25, 0.05, z], [0.6, 0.02, 0.08], 0x5f8a4a); // 花圃綠帶
        for (let i = 0; i < 6; i++) box([i * 0.1, 0.08, z], [0.03, 0.04, 0.03], tulips[(i + off) % 3]); // 鬱金香
      }
      tree(-0.55, 0.4, 0.35); tree(0.6, 0.45, 0.3);
      return true;
    }
    default:
      return false;
  }
}
